import { NextResponse } from 'next/server'
import { Resend } from 'resend'
import {
  escapeHtml,
  getClientIp,
  isValidEmail,
  rateLimit,
  sanitizeText,
} from '@/lib/security'

export const runtime = 'nodejs'

const OWNER_EMAIL = 'ckpmado@gmail.com'
const FROM_EMAIL = 'Portfolio <onboarding@resend.dev>'

export async function POST(request: Request) {
  const ip = getClientIp(request.headers)

  const limit = rateLimit(`contact:${ip}`, { limit: 3, windowMs: 60_000 })
  if (!limit.ok) {
    return NextResponse.json(
      { error: 'rate_limited' },
      { status: 429, headers: { 'Retry-After': String(limit.retryAfter) } },
    )
  }

  const contentType = request.headers.get('content-type') || ''
  if (!contentType.includes('application/json')) {
    return NextResponse.json({ error: 'invalid_request' }, { status: 415 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'invalid_request' }, { status: 400 })
  }

  const data = (body ?? {}) as Record<string, unknown>

  // Honeypot
  if (typeof data.website === 'string' && data.website.trim() !== '') {
    return NextResponse.json({ ok: true })
  }

  const name = sanitizeText(data.name, 100)
  const email = typeof data.email === 'string' ? data.email.trim() : ''
  const message = sanitizeText(data.message, 2000)

  if (!name || name.length < 2) {
    return NextResponse.json({ error: 'invalid_name' }, { status: 400 })
  }
  if (!isValidEmail(email)) {
    return NextResponse.json({ error: 'invalid_email' }, { status: 400 })
  }
  if (!message || message.length < 10) {
    return NextResponse.json({ error: 'invalid_message' }, { status: 400 })
  }

  const apiKey = process.env.RESEND_API_KEY
  if (!apiKey) {
    console.log('[v0] RESEND_API_KEY is not set — cannot send contact email')
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }

  try {
    const resend = new Resend(apiKey)
    const { data, error } = await resend.emails.send({
      from: FROM_EMAIL,
      to: OWNER_EMAIL,
      replyTo: email,
      subject: `New contact message from ${escapeHtml(name)}`,
      html: `<h2>New contact message</h2>
             <p><strong>Name:</strong> ${escapeHtml(name)}</p>
             <p><strong>Email:</strong> ${escapeHtml(email)}</p>
             <p><strong>Message:</strong></p>
             <p style="white-space:pre-wrap">${escapeHtml(message)}</p>
             <hr/>
             <p><strong>IP:</strong> ${escapeHtml(ip)}</p>`,
    })

    // IMPORTANT: the Resend SDK does NOT throw on API-level errors
    // (invalid/unverified domain, bad recipient, invalid key, etc.).
    // It resolves normally with { data: null, error: {...} }.
    // The old code never checked `error`, so it always answered the
    // client with { ok: true } even when nothing was actually sent.
    if (error) {
      console.log('[v0] Contact send failed:', error.message)
      return NextResponse.json({ error: 'server_error' }, { status: 500 })
    }

    console.log('[v0] Contact email sent:', data?.id)
    return NextResponse.json({ ok: true })
  } catch (error) {
    console.log('[v0] Contact send failed:', (error as Error).message)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

export function GET() {
  return NextResponse.json({ error: 'method_not_allowed' }, { status: 405 })
}
